                    candidate = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    c = route_cost(candidate)
                    if c + 1e-12 < best_cost:
                        best = candidate
                        best_cost = c
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [improve_route_2opt(r) for r in routes]

    # --------- inter-route relocate and swap ---------
    def feasible_with_extra(route, cid, extra=0.0):
        return route_demand(route) + demand_map.get(cid, 0.0) + extra <= capacity + 1e-12

    changed = True
    passes = 0
    while changed and passes < 3:
        changed = False
        passes += 1

        # relocate
        for i in range(len(routes)):
            r1 = routes[i]
            if not r1:
                continue
            base1 = route_cost(r1)
            for pos in range(len(r1)):
                cid = r1[pos]
                for j in range(len(routes)):
                    if i == j:
                        continue
                    r2 = routes[j]
                    if not feasible_with_extra(r2, cid):
                        continue
                    for ins in range(len(r2) + 1):
                        nr1 = r1[:pos] + r1[pos + 1:]
                        nr2 = r2[:ins] + [cid] + r2[ins:]
                        delta = route_cost(nr1) + route_cost(nr2) - base1 - route_cost(r2)
                        if delta + 1e-12 < 0:
                            routes[i] = improve_route_2opt(nr1)
                            routes[j] = improve_route_2opt(nr2)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break

        if changed:
            continue

        # swap
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                r1 = routes[i]
                r2 = routes[j]
                if not r1 or not r2:
                    continue
                base = route_cost(r1) + route_cost(r2)
                d1 = route_demand(r1)
                d2 = route_demand(r2)
                for a in range(len(r1)):
                    for b in range(len(r2)):
                        c1 = r1[a]
                        c2 = r2[b]
                        nd1 = d1 - demand_map.get(c1, 0.0) + demand_map.get(c2, 0.0)
                        nd2 = d2 - demand_map.get(c2, 0.0) + demand_map.get(c1, 0.0)
                        if nd1 > capacity + 1e-12 or nd2 > capacity + 1e-12:
                            continue
                        nr1 = r1[:a] + [c2] + r1[a + 1:]
                        nr2 = r2[:b] + [c1] + r2[b + 1:]
                        delta = route_cost(nr1) + route_cost(nr2) - base
                        if delta + 1e-12 < 0:
                            routes[i] = improve_route_2opt(nr1)
                            routes[j] = improve_route_2opt(nr2)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            if changed:
                break

    # Remove any empty routes
    routes = [r for r in routes if r]

    # Final validation repair: if any customer missing or duplicated, rebuild deterministically
    seen = {}
    for r in routes:
        for cid in r:
            seen[cid] = seen.get(cid, 0) + 1

    missing = [cid for cid in customer_ids if seen.get(cid, 0) == 0]
    duplicated = [cid for cid, cnt in seen.items() if cnt > 1]

    if missing or duplicated:
        # simple deterministic rebuild
        all_ids = sorted(customer_ids, key=seed_key)
        routes = []
        unserved = set(all_ids)
        while unserved:
            route = []
            load = 0.0
            last = depot_id
            while True:
                cand = []
                for cid in all_ids:
                    if cid not in unserved:
                        continue
                    dem = demand_map.get(cid, 0.0)
                    if load + dem <= capacity + 1e-12:
                        cand.append((dist(coords.get(last, None), coords.get(cid, None)), -dem, str(cid), cid))
                if not cand:
                    break
                cand.sort()
                cid = cand[0][3]
                route.append(cid)
                unserved.remove(cid)
                load += demand_map.get(cid, 0.0)
                last = cid
            routes.append(route)

    return routes
